from assemble_evidence import *
rows=[]
def add(rid,fn,quote,note,org='',verdict='KEEP',amount='',**kw):
    assert ' '.join(quote.split()) in ' '.join(text(fn).split()),(rid,quote)
    rows.append(base(rid,fn,quote,note,amount,org_id=org,verdict=verdict,**kw))
